#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iostream>

int main() {
    if (!std::ofstream("from.txt").put('a')) // create and write to file
    {
        std::perror("Error creating from.txt");
        return EXIT_FAILURE;
    }

    if (std::rename("from.txt", "to.txt")) {
        std::perror("Error renaming");
        return EXIT_FAILURE;
    }

    std::cout << std::ifstream("to.txt").rdbuf() << '\n'; // print file
    return EXIT_SUCCESS;
}
